import React, { useEffect } from 'react';

import Grid from '@mui/material/Unstable_Grid2';

import { useSelector, useDispatch } from 'src/redux/store';
import { getWallet, getTransactions } from 'src/redux/slices/wallet';

import AccountTransactionWallet from './account-transaction-wallet';
import AccountTransactionHistory from './account-transaction-history';
// ----------------------------------------------------------------------

export default function AccountTransaction() {
  const dispatch = useDispatch();
  const { wallet, transactions } = useSelector((state) => state.wallet);

  useEffect(() => {
    dispatch(getWallet());
    dispatch(getTransactions());
  }, [dispatch]);

  return (
    <Grid container spacing={3} disableEqualOverflow>
      <Grid xs={12} md={4}>
        <AccountTransactionWallet wallet={wallet} />
      </Grid>
      <Grid xs={12} md={8}>
        <AccountTransactionHistory transactions={transactions} wallet={wallet} />
      </Grid>
    </Grid>
  );
}
